from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];D=R;p=json.loads((D/'plan.json').read_text());E=html.escape
BASE='https://auraofintelligence.github.io/7-mile-admin-prep/'
pages=[('index','Overview','7-Mile, from idea to organised work.','A practical planning and administration hub for two Indigenous-led entities, permanent community living, cultural activities, food growing, making and stays.','overview'),('plan','Original plan','Bring the 7-Mile concept into the work.','Community living, site layout, food growing, shared facilities and connected labs, mapped to tasks and documents.','overview'),('tasks','Task register','Know the next useful task.','Decisions, documents, registrations and dependencies in one searchable working register.','tasks'),('documents','Document studio','Turn a decision into a useful document.',f"{len(p['docs'])} focused briefs, each with inputs, checklists, references and an AI master prompt.",'documents'),('checklists','Checklists','Work through one stage at a time.','Establishment, approvals and operating readiness, grouped into practical checklists.','checklists'),('references','References','Start with useful precedents.','Official templates, download links, comparable rule books and planning sources.','references'),('agencies','Agency directory','Take the question to the right place.','Council, state and federal roles for establishment, tourism and development on Minjerribah.','agencies'),('decisions','Decisions & records','Keep the choices and evidence clear.','Expressed intentions, open founding decisions and the source trail for this workbench.','decisions'),('sitemap','Site tree','See the whole workbench.','Every main destination, checklist and individual document page in one navigable tree.','sitemap')]
nav=''.join(f'<a href="{f}.html">{E(t)}</a>' for f,t,*_ in pages)
def page(f,title,h,sub,image,doc=''):
 canonical=BASE+('' if f=='index' else f+'.html')
 s=f'''<!doctype html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | 7-Mile planning & administration</title><meta name="description" content="{E(sub)}"><meta name="theme-color" content="#163d32"><link rel="icon" href="assets/favicon.png" type="image/png"><link rel="icon" href="assets/favicon.ico" sizes="any"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="stylesheet" href="styles.css"><script src="data.js" defer></script><script src="app.js" defer></script></head>
<body id="top" data-page="{f}.html" data-doc="{doc}"><a href="#content" class="skip">Skip to content</a><header class="site-header"><a href="index.html" class="brand"><img src="assets/favicon.png" width="40" height="40" alt="7-Mile"><span><strong>7-Mile</strong><small>Planning & administration</small></span></a><nav class="site-nav desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="site-nav" aria-label="Mobile navigation">{nav}</nav></details></header><section class="hero"><img src="assets/{image}.webp" alt="Island bushland and community working spaces" width="1536" height="1024"><div class="hero-copy"><p class="eyebrow">MINJERRIBAH · INDIGENOUS-LED · WORKING PLAN</p><h1>{E(h)}</h1><p>{E(sub)}</p></div></section><main id="content"><noscript><h2>7-Mile planning data</h2><p>The interactive workbench uses JavaScript. <a href="plan.json">Download the complete plan</a>, <a href="tasks.csv">tasks CSV</a> or <a href="documents.csv">document register</a>.</p></noscript></main><nav class="route-nav" id="route-nav" aria-label="Previous and next page"><a href="index.html">Overview</a><a href="sitemap.html">Site tree</a></nav><footer class="site-footer"><div><strong>7-Mile planning & administration</strong><p>Working proposal for Minjerribah / North Stradbroke Island.</p><p>Prepared 10 October 2026 · Review and founding decisions remain open.</p></div><div class="footer-links"><a href="sitemap.html">Site tree</a><a href="references.html">References</a><a href="https://github.com/auraofintelligence/7-mile-admin-prep" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></footer><button id="top-button" aria-label="Return to top" title="Return to top">↑</button><div id="live" class="sr-only" role="status" aria-live="polite"></div></body></html>'''
 s=s.replace('<meta name="theme-color"', '<link rel="canonical" href="'+canonical+'"><meta property="og:url" content="'+canonical+'"><meta name="theme-color"')
 (D/(f+'.html')).write_text(s)
 legacy=D/'dist';legacy.mkdir(exist_ok=True)
 (legacy/(f+'.html')).write_text(f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | 7-Mile</title><link rel="canonical" href="{canonical}"><script>location.replace('../{f}.html'+location.search+location.hash)</script></head><body><p><a href="../{f}.html">Open {E(title)}</a>.</p></body></html>\n''')
for f,t,h,s,img in pages:page(f,t,h,s,img)
for d in p['docs']:
 img={'Foundations':'decisions','Entities':'documents','Relationships':'agencies','Governance':'references','Land & approvals':'checklists','Business & operations':'overview'}[d['group']]
 page('document-'+d['id'],d['title'],d['title'],d['purpose'],img,d['id'])
(D/'.nojekyll').write_text('')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\n\nSitemap: '+BASE+'sitemap.xml\n')
routes=[f for f,*_ in pages]+['document-'+d['id'] for d in p['docs']]
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+BASE+('' if f=='index' else f+'.html')+'</loc></url>\n' for f in routes)+'</urlset>\n')
print('Built',len(pages)+len(p['docs']),'HTML pages')
